"""Publish target input prototype, bus failure/control and cost evidence."""
import shutil,subprocess
from datetime import datetime,timezone
from pathlib import Path
from publish_scene_reset_fresh_v1 import ROOT,V,P,read,save,sha,atomic
def main():
 manifest=V/'native-Deck-current-status-v1-current.json';w=read(manifest)
 for p,h in w['dependencies_sha256'].items():assert sha(p)==h,p
 names=['native-deck-retained-input-clr-v1','native-geometry-input-clr-v1','input-clr-public-bus-v1','input-clr-cost-v1','input-clr-copied-rebuild-v1','native-deck-retained-input-primitives-v1','native-geometry-input-primitives-v1','input-primitives-public-bus-v1','input-baseline-public-bus-v1']
 proofs={n:read(V/(n+'-current.json'))for n in names};ret,geo,bus,cost,copy=[proofs[n]for n in names[:5]]
 for n in names[:7]:
  g=proofs[n];assert g['status'].startswith('terminal_')and'failed'not in g['status'],n
  for p,h in g.get('source_sha256',{}).items():assert sha(p)==h,(n,p)
 assert ret['completed']==4992 and ret['fallback_cases']==16 and geo['completed']==256 and bus['completed']==13
 assert ret['payload_sha256']==geo['payload_sha256']==bus['payload_sha256']==copy['sha256']
 for n in names[7:]:assert proofs[n]['status']=='terminal_public_input_bus_order_failed'
 out=V/'native-input-clr-reviewed-v1'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
 for n,g in proofs.items():
  save(out/(n+'.json'),g);subprocess.run(['/bin/cp','-cR',g['directory'],str(out/n)],check=True,capture_output=True)
 for rel in ['scripts/check_input_baseline_public_bus_v1.py','scripts/check_input_primitives_public_bus_v1.py']:
  f=out/'failure-sources'/Path(rel).name;f.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(ROOT/rel,f)
 src=ROOT/'projects/black-ice-white-noise/restoration/native-m68k/deck-shared-v21-input-native-clr';subprocess.run(['/bin/cp','-cR',str(src),str(out/src.name)],check=True,capture_output=True)
 old=read(Path(read(V/'scene-reset-input-cost-v1-current.json')['directory'])/'cases.json');new=read(Path(cost['directory'])/'cases.json');comparisons=[]
 for a,b in zip(old,new):
  assert a['variant']==b['variant']and a['costs']['original']==b['costs']['original'];x=a['costs']['compiled']['cycles'];y=b['costs']['compiled']['cycles'];comparisons.append(dict(variant=a['variant'],original_cycles=b['costs']['original']['cycles'],previous_native_cycles=x,new_native_cycles=y,reduction_percent=round(100*(1-y/x),2),new_vs_original_ratio=round(y/b['costs']['original']['cycles'],4)))
 save(out/'cost-comparisons.json',comparisons)
 facts=dict(status='terminal_target_input_CLR_prototype_CPU_bus_and_cost_pass',entry='0x11b4c',source_profile=src.name,source_directory=str(src),authorship='Coordinator target bus/flag specialization and seven explicit original CLR sites;not new local model source',canonical_algorithm_preserved_except_explicit_CLR_sites=True,explicit_CLR_sites=7,body_cases=2048,original_instruction_locations_observed=ret['coverage']['input'],retained_caller_cases=4992,retained_fallback_cases=16,geometry_regression_cases=256,actual_public_bus_order_cases=13,baseline_bus_case0_pass=False,baseline_case0_original_events=11,baseline_case0_native_events=7,prior_v20_final_CPU_RAM_pass_but_bus_failed=True,module_bytes=ret['code_bytes'],module_sha256=ret['payload_sha256'],input_C_stack_peak=ret['maximum_C_stack_bytes']['input'],previous_input_C_stack_peak=120,geometry_C_stack_peak=geo['maximum_C_stack_bytes'],new_arena_bytes=0,copied_module_byte_identical=True,cost_measured=True,cost_sample_pairs=8,native_input_cycle_reduction_percent_range=[min(x['reduction_percent']for x in comparisons),max(x['reduction_percent']for x in comparisons)],native_input_vs_original_cycle_ratio_range=[min(x['new_vs_original_ratio']for x in comparisons),max(x['new_vs_original_ratio']for x in comparisons)],cost_approved=False,prototype_only=True,experimental_disc_function_replaced=False,previous_experimental_disc_has_older_native_input=True,new_disc_built=False,fresh_gameplay_tested=False,installed_preview_changed=False,new_training=False,actual_new_model_predictions=0,native_Chat_display_verified=False,scope='Exact target prototype address0x16dc00/arena0x179200. Same structured canonical input;existing native flag/direct bus primitives and7explicitCLRsites. FullCPU/nonarenaRAM/helper entries and original stack match,including all2048inputcases,allCCR/bothbanks and real reset. Other record/poll/texture helpers are declared effects. Actual trace checks globals0x40000..4ffff anddescriptor0x80000..900ff in13cases;private/gueststacks and instructionfetch excluded;recorder lacks width. No arbitraryIRQ/reentry or fresh-gameplay/physical-console proof. Eight cost samples omit declared helper execution;27..34percent lower native input work remains8.7..16.1times original. Prototype not deployed.',next_action='Qualify the new input prototype in a final disc layout,alias/connected/observer boundaries and fresh ordinary reset route. Preserve the actual current-disc bus-order failure;do not claim it fixed until the new image is built and checked. Continue whole-game CPU/GPU/DSP/HLE replacement and useful local-model training/evaluation.')
 report=ROOT/'reports/Native Input Primitive and CLR Prototype Review.txt';facts['report']=str(report);save(out/'facts.json',facts)
 report.write_text('BIWN input prototype — native primitives and explicit CLR semantics\n\n'
  'The first v20prototype preserved finalCPU/RAM but failed actual public-bus order. The older v19experimental input has the same checked case0failure:11original bus events versus7native events. Four physical CLR operand reads were missing in that case. Both failures are retained. This demonstrates that earlier final-state checks did not prove public-bus fidelity.\n\n'
  'v21uses existing qualified native flag/directRAM primitives and replaces seven original CLR write sites with explicit68000CLR operations. Ordinary MOVE zero values keep MOVE behavior. The structured input algorithm and supplied reset body otherwise remain unchanged;this is coordinator source work,not model-authored code or training.\n\n'
  'v21passes4992retained cases+16fallbacks,including2048inputcases acrossallCCR/bothbanks. All256geometry regressions pass with real original formatter/text and actualblitter effects;GPU services remain declared fixtures where specified. Thirteen actual public-bus input traces match kind/address/value order,including original versus native reset. Width is not recorded by this core trace. Guest/private stacks are excluded from those watched trace ranges;separate semantic/stack gates cover their final states. Input Cstack112bytes versus120previously;geometry164/176. Copied package rebuilds identical38594byte module.\n\n'
  'Eight fixed input samples retain matchingCPU/nonarenaRAM/helperentries. Native input cycles fall27.15..33.56percent versusv19,including the added CLR reads. New input still costs8.69..16.12times original in those samples. Declared helper execution is excluded;this is not full-game or physical-console timing. The reset dispatcher itself remains1760versus612original-bodycycles with unequal boundaries. No performance approval or game fidelity claim.\n\n'
  'Prototype only. No new disc,Desktop preview,weights or adapter changed. Final layout,alias/connected/observer and fresh ordinary input/reset checks remain required before adoption. Whole-game source rebuilding,arbitraryIRQ fidelity and broad local-model quality remain incomplete.\n\n'+str(out/'cost-comparisons.json')+'\n')
 packet=read(w['packet']);save(out/'before-packet.json',packet);packet['previous_latest_source_development']=packet['latest_source_development'];packet['latest_source_development']=packet['native_input_optimization_progress']=facts;packet['latest_native_candidate']['public_input_bus_case0_verified']=False;packet['latest_native_candidate']['public_input_bus_case0_original_native_events']=[11,7];packet['latest_native_candidate']['next_action']=facts['next_action'];packet['latest_fresh_reviewed_candidate']=packet['latest_native_candidate'];packet['current_copied_Reader_progress'].update(latest_source_changed_since_last_prediction=True,current_source_reply_verified=False);save(out/'current-status-packet.json',packet);shutil.copy2(__file__,out/'publisher-source.py')
 deps={str(p):sha(p)for p in out.rglob('*')if p.is_file()};deps[str(report)]=sha(report)
 pub=V/'native-input-clr-reviewed-v1-current.json';atomic(pub,dict(status=facts['status'],directory=str(out),facts=str(out/'facts.json'),report=str(report),new_predictions=0,new_training=False,new_disc_built=False,whole_objective_complete=False,dependencies_sha256=deps))
 w.update(packet=str(out/'current-status-packet.json'),dependencies_sha256={**w['dependencies_sha256'],**deps,str(pub):sha(pub)});atomic(manifest,w)
 index=ROOT/'config/current-model-work-sources.json';items=read(index);items=[x for x in items if x[0]!=pub.name];items.append([pub.name,'BIWN input native primitive/CLR prototype;actual baseline bus failure preserved']);atomic(index,items)
 for p,h in w['dependencies_sha256'].items():
  source=Path(p);assert source.is_relative_to(ROOT);dest=P/'workbench'/source.relative_to(ROOT);dest.parent.mkdir(parents=True,exist_ok=True)
  if not dest.is_file()or sha(dest)!=h:subprocess.run(['/bin/cp','-c',str(source),str(dest)],check=True,capture_output=True)
 shutil.copy2(manifest,P/'workbench/verification'/manifest.name);shutil.copy2(index,P/'workbench/config'/index.name)
 print(facts['status'],facts['native_input_cycle_reduction_percent_range'],flush=True)
if __name__=='__main__':main()
